files.content:
html {
  block-size: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  background-image: linear-gradient(to bottom, #000 50%, #424242 50%);
  block-size: 100%;
}

.landscape {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  background-image: url(https://code.s3.yandex.net/web-code/images/04-beautischa/portal-background.svg);
  background-size: cover;
  inline-size: 100%;
  aspect-ratio: 1 / 1;
}

.landscape::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: url(https://code.s3.yandex.net/web-code/images/04-beautischa/portal-foreground.svg);
}

img {
  max-inline-size: 250px;
}

.portal {
  display: flex;
  justify-content: center;
  align-items: center;
  background-image: repeating-conic-gradient( #f43b29 0 15deg, #09a3ea 15deg 30deg );
  inline-size: 25%;
  block-size: 50%;
}
